function flattenGroups(groups, depth) {
  const result = [];
  const visit = value => {
    if (Array.isArray(value)) value.forEach(visit);
    else result.push(value);
  };
  groups.forEach(visit);
  return result;
}
module.exports = { flattenGroups };

