const test = require('node:test');
const assert = require('node:assert/strict');
const { flattenGroups } = require('../src/navigation-groups.cjs');

test("omitted depth is one and depth zero makes a shallow copy", () => {
  const deep = ['cedar'];
  const nested = ['pine', deep];
  const groups = ['oak', nested];
  assert.deepEqual(flattenGroups(groups), ['oak', 'pine', ['cedar']]);
  const zero = flattenGroups(groups, 0);
  assert.deepEqual(zero, groups);
  assert.notEqual(zero, groups);
  assert.equal(zero[1], nested);
  assert.deepEqual(groups, ['oak', ['pine', ['cedar']]]);
});

test("holes disappear only in levels that are flattened", () => {
  const inner = ['leaf', , 'twig'];
  const groups = ['root', , ['branch', , inner], undefined];
  const once = flattenGroups(groups);
  assert.deepEqual(once, ['root', 'branch', inner, undefined]);
  assert.equal(once[2], inner);
  assert.equal(1 in once[2], false);
  assert.deepEqual(flattenGroups(groups, 2), ['root', 'branch', 'leaf', 'twig', undefined]);
  assert.equal(1 in groups, false);
  assert.equal(1 in groups[2], false);
});

test("depth zero removes root holes but preserves nested holes and references", () => {
  const leaf = {label: 'fern'};
  const inner = [leaf, , 'twig'];
  const groups = [, inner, undefined, leaf];
  const result = flattenGroups(groups, 0);
  assert.deepEqual(result, [inner, undefined, leaf]);
  assert.notEqual(result, groups);
  assert.equal(result[0], inner);
  assert.equal(result[2], leaf);
  assert.equal(1 in inner, false);
  assert.equal(0 in groups, false);
});

